type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

const success: Result<number> = { ok: true, value: 42 };
const failure: Result<number, string> = { ok: false, error: 'timeout' };

function createList<T = string>(items: T[] = []): T[] {
  return [...items];
}

const strings = createList();        // string[]
const nums = createList<number>([]); // number[]

// Legacy pattern — avoid:
type LegacyStore<T = any> = { get(): T };

// Prefer:
type SafeStore<T = unknown> = { get(): T };

const store: SafeStore = { get: () => JSON.parse('{}') };
// Must narrow after get()
